// The NESTED install -- the one Node's resolution actually reaches from
// vt2-runner-lib/index.js, and therefore the only instance the application
// can call. Identical in name, version and export name to the top-level
// twin beside it.
function dangerousOp(input) {
  return reachedSink(input);
}

function reachedSink(input) {
  return "reached-sink:" + input;
}

exports.dangerousOp = dangerousOp;
